mapper.select:
SELECT *
FROM lunaerp_finance_payment
WHERE id = #{id}
  AND deleted = 1
  AND approval_status = 'PENDING'
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_finance_payment
SET deleted = 0,
    approval_status = 'PENDING',
    updater = #{updater},
    update_time = #{now}
WHERE id = #{id}
  AND deleted = 1
  AND approval_status = 'PENDING'
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_finance_payment
WHERE id = #{id}
  AND deleted = 1
  AND approval_status = 'PENDING'
  AND tenant_id = #{tenantId}
